1	/**
2	 * Build locale-specific TypeDoc output.
3	 *
4	 * EN API docs are generated directly by TypeDoc to `docs/api/`.
5	 * HU API docs are cloned to `docs/hu/api/` and then localized with the configured adapter.
6	 */
7	import {
8	  cpSync,
9	  existsSync,
10	  mkdirSync,
11	  readdirSync,
12	  readFileSync,
13	  rmSync,
14	  statSync,
15	  writeFileSync,
16	} from "node:fs";
17	import { dirname, join, relative } from "node:path";
18	import { spawnSync } from "node:child_process";
19	import { createTranslationAdapter } from "./api-translation.ts";
20	import {
21	  type TranslationUnit,
22	  TranslationMemory,
23	  keyFor,
24	  translateUnits,
25	} from "./translation-memory.ts";
26	
27	const docsRoot = join(import.meta.dirname, "..");
28	const enApiDir = join(docsRoot, "api");
29	const huApiDir = join(docsRoot, "hu/api");
30	
31	const run = (command: string, args: string[]): void => {
32	  const result = spawnSync(command, args, {
33	    cwd: docsRoot,
34	    stdio: "inherit",
35	  });
36	
37	  if (result.status !== 0) {
38	    throw new Error(`${command} ${args.join(" ")} failed with exit code ${result.status ?? -1}`);
39	  }
40	};
41	
42	const walkFiles = (dir: string): string[] => {
43	  if (!existsSync(dir)) {
44	    return [];
45	  }
46	
47	  const files: string[] = [];
48	  for (const name of readdirSync(dir)) {
49	    const fullPath = join(dir, name);
50	    const stat = statSync(fullPath);
51	    if (stat.isDirectory()) {
52	      files.push(...walkFiles(fullPath));
53	    } else {
54	      files.push(fullPath);
55	    }
56	  }
57	  return files;
58	};
59	
60	type SidebarItem = {
61	  text?: string;
62	  link?: string;
63	  items?: SidebarItem[];
64	};
65	
66	const translateSidebar = (item: SidebarItem, translate: (text: string) => string): SidebarItem => {
67	  const translated: SidebarItem = { ...item };
68	
69	  if (translated.text) {
70	    translated.text = translate(translated.text);
71	  }
72	
73	  if (translated.items) {
74	    translated.items = translated.items.map((child) => translateSidebar(child, translate));
75	  }
76	
77	  return translated;
78	};
79	
80	/** Collect every `text` label in a sidebar tree (for one batched translation pass). */
81	const collectSidebarText = (items: SidebarItem[], out: string[]): void => {
82	  for (const item of items) {
83	    if (item.text) out.push(item.text);
84	    if (item.items) collectSidebarText(item.items, out);
85	  }
86	};
87	
88	const build = (): void => {
89	  const adapter = createTranslationAdapter();
90	  const memory = TranslationMemory.load("hu", "api");
91	
92	  rmSync(enApiDir, { recursive: true, force: true });
93	  rmSync(huApiDir, { recursive: true, force: true });
94	
95	  console.log("Generating EN API docs...");
96	  run("pnpm", ["exec", "typedoc", "--options", "typedoc.json", "--out", "api"]);
97	  run("node", ["scripts/style-api-badges.ts"]);
98	  run("node", ["scripts/write-api-overview.ts"]);
99	
100	  // The CSS API pages live under docs/api/css/; generate them after TypeDoc (which cleans docs/api) and
101	  // before the locale clone, so they're cloned + translated for HU for free.
102	  console.log("Generating CSS API docs...");
103	  run("node", ["scripts/build-css-api.ts"]);
104	
105	  console.log("Cloning API docs for HU locale...");
106	  mkdirSync(dirname(huApiDir), { recursive: true });
107	  cpSync(enApiDir, huApiDir, { recursive: true });
108	
109	  const files = walkFiles(huApiDir);
110	  const markdownFiles = files.filter((f) => f.endsWith(".md"));
111	  // The TypeDoc sidebar carries the CSS section too (merged by @cssdoc/typedoc), so its labels cover
112	  // both the TS API and the CSS reference.
113	  const sidebarFiles = files.filter((f) => f.endsWith("typedoc-sidebar.json"));
114	
115	  // 1. Markdown: diff each file against the memory; only misses reach the adapter.
116	  const markdownUnits: (TranslationUnit & { filePath: string })[] = markdownFiles.map(
117	    (filePath) => ({
118	      kind: "markdown",
119	      source: readFileSync(filePath, "utf8"),
120	      filePath,
121	    }),
122	  );
123	  const markdownTranslations = translateUnits(adapter, memory, markdownUnits, { autosave: true });
124	  for (const unit of markdownUnits) {
125	    writeFileSync(
126	      unit.filePath,
127	      markdownTranslations.get(keyFor("markdown", unit.source)) ?? unit.source,
128	    );
129	  }
130	
131	  // 2. Sidebars: collect every label across all trees, translate the misses in one batched pass,
132	  //    then rebuild each tree from the results.
133	  const sidebars = sidebarFiles.map((filePath) => ({
134	    filePath,
135	    tree: JSON.parse(readFileSync(filePath, "utf8")) as SidebarItem[],
136	  }));
137	  const labels: string[] = [];
138	  for (const { tree } of sidebars) collectSidebarText(tree, labels);
139	  const labelTranslations = translateUnits(
140	    adapter,
141	    memory,
142	    labels.map((source) => ({ kind: "text", source })),
143	  );
144	  const translateLabel = (text: string): string =>
145	    labelTranslations.get(keyFor("text", text)) ?? text;
146	  for (const { filePath, tree } of sidebars) {
147	    const translated = tree.map((item) => translateSidebar(item, translateLabel));
148	    writeFileSync(filePath, `${JSON.stringify(translated, null, 2)}\n`);
149	  }
150	
151	  memory.save();
152	  console.log(
153	    `Localized ${markdownFiles.length} API markdown files + ${labels.length} sidebar labels for HU ` +
154	      `via '${adapter.name}' (${memory.misses} translated, ${memory.hits} cached) in ${relative(docsRoot, huApiDir)}`,
155	  );
156	};
157	
158	build();
159

1	/**
2	 * Locale translation adapter primitives for generated API docs.
3	 *
4	 * The default adapter is deterministic and keyless (safe for CI), while the adapter contract keeps
5	 * room for higher-quality engines later.
6	 */
7	import { spawnSync } from "node:child_process";
8	
9	export interface TranslationAdapter {
10	  readonly name: string;
11	  translateMarkdown(input: string, filePath: string): string;
12	  translateText(input: string): string;
13	  /**
14	   * Translate many short strings in one request. Returns a map keyed by each item's `id`. Optional:
15	   * callers fall back to per-item {@link TranslationAdapter.translateText} when it's absent.
16	   */
17	  translateBatch?(items: readonly { id: string; text: string }[]): Record<string, string>;
18	}
19	
20	const SORTED_REPLACEMENTS: Array<[RegExp, string]> = [
21	  [/\bType Parameters\b/g, "Típusparaméterek"],
22	  [/\bType parameter\b/g, "Típusparaméter"],
23	  [/\bParameters\b/g, "Paraméterek"],
24	  [/\bParameter\b/g, "Parameter"],
25	  [/\bReturns\b/g, "Visszatérés"],
26	  [/\bReturn type\b/g, "Visszatérési típus"],
27	  [/\bThrows\b/g, "Kivételek"],
28	  [/\bDefined in\b/g, "Definiálva itt"],
29	  [/\bInherited from\b/g, "Örökölve innen"],
30	  [/\bImplemented by\b/g, "Implementálja"],
31	  [/\bImplementation of\b/g, "Implementációja"],
32	  [/\bOverrides\b/g, "Felülírja"],
33	  [/\bProperties\b/g, "Tulajdonságok"],
34	  [/\bProperty\b/g, "Tulajdonság"],
35	  [/\bMethods\b/g, "Metódusok"],
36	  [/\bMethod\b/g, "Metódus"],
37	  [/\bFunctions\b/g, "Függvények"],
38	  [/\bFunction\b/g, "Függvény"],
39	  [/\bVariables\b/g, "Változók"],
40	  [/\bVariable\b/g, "Változó"],
41	  [/\bInterfaces\b/g, "Interfészek"],
42	  [/\bInterface\b/g, "Interfész"],
43	  [/\bClasses\b/g, "Osztályok"],
44	  [/\bClass\b/g, "Osztály"],
45	  [/\bConstructors\b/g, "Konstruktorok"],
46	  [/\bConstructor\b/g, "Konstruktor"],
47	  [/\bEnumerations\b/g, "Felsorolások"],
48	  [/\bEnumeration\b/g, "Felsorolás"],
49	  [/\bType Aliases\b/g, "Típusaliasok"],
50	  [/\bType Alias\b/g, "Típusalias"],
51	  [/\bReferences\b/g, "Hivatkozások"],
52	  [/\bReference\b/g, "Hivatkozás"],
53	  [/\bReadonly\b/g, "Csak olvasható"],
54	  [/\bOptional\b/g, "Opcionális"],
55	  [/\bDeprecated\b/g, "Elavult"],
56	  [/\bExample\b/g, "Példa"],
57	  [/\bExamples\b/g, "Példák"],
58	  [/\bSee also\b/g, "Lásd még"],
59	  [/\bHierarchy\b/g, "Hierarchia"],
60	  [/\bIndex\b/g, "Index"],
61	  [/\bPackage\b/g, "Csomag"],
62	  [/\bModule\b/g, "Modul"],
63	  [/\bNamespaces\b/g, "Névterek"],
64	  [/\bNamespace\b/g, "Névtér"],
65	  [/\bCall Signature\b/g, "Hívási szignatúra"],
66	  [/\bSignatures\b/g, "Szignatúrák"],
67	  [/\bSignature\b/g, "Szignatúra"],
68	  [/\bDescription\b/g, "Leírás"],
69	  [/\bDefault Value\b/g, "Alapértelmezett érték"],
70	  [/\bSource\b/g, "Forrás"],
