74	
75	export class GlossaryTranslationAdapter implements TranslationAdapter {
76	  readonly name = "glossary";
77	
78	  translateMarkdown(input: string): string {
79	    return translateWithoutFencedCode(input, (text) => this.translateText(text));
80	  }
81	
82	  translateText(input: string): string {
83	    const preserved = preservePackageNames(input);
84	    let out = preserved.text;
85	    for (const [pattern, value] of SORTED_REPLACEMENTS) {
86	      out = out.replace(pattern, value);
87	    }
88	    return restorePackageNames(out, preserved.packageNames);
89	  }
90	
91	  translateBatch(items: readonly { id: string; text: string }[]): Record<string, string> {
92	    return Object.fromEntries(items.map((item) => [item.id, this.translateText(item.text)]));
93	  }
94	}
95	
96	const replaceBlocks = (
97	  input: string,
98	  pattern: RegExp,
99	  markerPrefix: string,
100	): { text: string; blocks: string[] } => {
101	  const blocks: string[] = [];
102	  const text = input.replace(pattern, (match) => {
103	    const marker = `__${markerPrefix}_${blocks.length}__`;
104	    blocks.push(match);
105	    return marker;
106	  });
107	  return { text, blocks };
108	};
109	
110	const restoreBlocks = (input: string, blocks: string[], markerPrefix: string): string => {
111	  let out = input;
112	  for (const [index, block] of blocks.entries()) {
113	    out = out.replaceAll(`__${markerPrefix}_${index}__`, block);
114	  }
115	  return out;
116	};
117	
118	const preserveMarkdownSensitiveBlocks = (
119	  input: string,
120	): {
121	  text: string;
122	  codeBlocks: string[];
123	  inlineCodeBlocks: string[];
124	} => {
125	  const fenced = replaceBlocks(input, /```[\s\S]*?```/g, "PTK_CODE_BLOCK");
126	  const inline = replaceBlocks(fenced.text, /`[^`\n]+`/g, "PTK_INLINE_CODE");
127	  return {
128	    text: inline.text,
129	    codeBlocks: fenced.blocks,
130	    inlineCodeBlocks: inline.blocks,
131	  };
132	};
133	
134	const restoreMarkdownSensitiveBlocks = (
135	  input: string,
136	  codeBlocks: string[],
137	  inlineCodeBlocks: string[],
138	): string => {
139	  const withCode = restoreBlocks(input, codeBlocks, "PTK_CODE_BLOCK");
140	  return restoreBlocks(withCode, inlineCodeBlocks, "PTK_INLINE_CODE");
141	};
142	
143	const preservePackageNames = (input: string): { text: string; packageNames: string[] } => {
144	  const packagePattern = /@[a-z0-9][a-z0-9.-]*\/[a-z0-9][a-z0-9.-]*/gi;
145	  const packageNames: string[] = [];
146	
147	  const text = input.replace(packagePattern, (match) => {
148	    const marker = `__PTK_PACKAGE_${packageNames.length}__`;
149	    packageNames.push(match);
150	    return marker;
151	  });
152	
153	  return { text, packageNames };
154	};
155	
156	/** Pull the first `{…}` JSON object out of a model response (tolerating code fences), or `null`. */
157	const extractJsonObject = (raw: string): Record<string, unknown> | null => {
158	  const start = raw.indexOf("{");
159	  const end = raw.lastIndexOf("}");
160	  if (start === -1 || end <= start) return null;
161	  try {
162	    const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
163	    return typeof parsed === "object" && parsed !== null
164	      ? (parsed as Record<string, unknown>)
165	      : null;
166	  } catch {
167	    return null;
168	  }
169	};
170	
171	const restorePackageNames = (input: string, packageNames: string[]): string => {
172	  let out = input;
173	  for (const [index, packageName] of packageNames.entries()) {
174	    out = out.replaceAll(`__PTK_PACKAGE_${index}__`, packageName);
175	  }
176	  return out;
177	};
178	
179	const translateWithoutFencedCode = (input: string, translate: (line: string) => string): string => {
180	  const lines = input.split("\n");
181	  const out: string[] = [];
182	  let inFence = false;
183	
184	  for (const line of lines) {
185	    if (line.trimStart().startsWith("```")) {
186	      inFence = !inFence;
187	      out.push(line);
188	      continue;
189	    }
190	
191	    if (inFence) {
192	      out.push(line);
193	      continue;
194	    }
195	
196	    out.push(translate(line));
197	  }
198	
199	  return out.join("\n");
200	};
201	
202	export class ClaudeCodeTranslationAdapter implements TranslationAdapter {
203	  readonly name = "claude-code";
204	
205	  private readonly command: string;
206	  private readonly args: string[];
207	
208	  constructor() {
209	    this.command = process.env.DOCS_TRANSLATION_COMMAND ?? "claude";
210	    this.args = (process.env.DOCS_TRANSLATION_COMMAND_ARGS ?? "")
211	      .split(" ")
212	      .map((part) => part.trim())
213	      .filter((part) => part.length > 0);
214	  }
215	
216	  translateMarkdown(input: string, filePath: string): string {
217	    const preservedMarkdown = preserveMarkdownSensitiveBlocks(input);
218	    const preservedPackages = preservePackageNames(preservedMarkdown.text);
219	    const prompt = [
220	      "Translate this technical markdown from English to Hungarian.",
221	      "Return only the translated markdown.",
222	      "Rules:",
223	      "- Keep markdown structure unchanged.",
224	      "- Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__ or __PTK_INLINE_CODE_#__.",
225	      "- Do not alter placeholder tokens like __PTK_PACKAGE_#__.",
226	      "- Preserve whitespace and line breaks.",
227	      "- Keep import paths, package names, URLs, and identifiers intact.",
228	      `File: ${filePath}`,
229	      "--- BEGIN MARKDOWN ---",
230	      preservedPackages.text,
231	      "--- END MARKDOWN ---",
232	    ].join("\n");
233	
234	    const translated = this.runClaude(prompt, `markdown file ${filePath}`);
235	    const restoredPackages = restorePackageNames(translated, preservedPackages.packageNames);
236	    return restoreMarkdownSensitiveBlocks(
237	      restoredPackages,
238	      preservedMarkdown.codeBlocks,
239	      preservedMarkdown.inlineCodeBlocks,
240	    );
241	  }
242	
243	  translateText(input: string): string {
244	    const preserved = preservePackageNames(input);
245	    const prompt = [
246	      "Translate this technical UI text from English to Hungarian.",
247	      "Return only the translation.",
248	      "Keep identifiers and package names unchanged.",
249	      "Do not alter placeholder tokens like __PTK_PACKAGE_#__.",
250	      "Text:",
251	      preserved.text,
252	    ].join("\n");
253	
254	    const translated = this.runClaude(prompt, "single text line").trim();
255	    return restorePackageNames(translated, preserved.packageNames);
256	  }
257	
258	  translateBatch(items: readonly { id: string; text: string }[]): Record<string, string> {
259	    const out: Record<string, string> = {};
260	    // Chunk by total character budget so each request stays small enough to round-trip reliably.
261	    const BUDGET = 6000;
262	    let chunk: { id: string; text: string }[] = [];
263	    let size = 0;
264	    const flush = (): void => {
265	      if (chunk.length > 0) Object.assign(out, this.runBatch(chunk));
266	      chunk = [];
267	      size = 0;
268	    };
269	    for (const item of items) {
270	      if (size + item.text.length > BUDGET && chunk.length > 0) flush();
271	      chunk.push(item);
272	      size += item.text.length;
273	    }
274	    flush();
275	    return out;
276	  }
277	
278	  /** Translate one chunk of short strings as a single JSON object; fall back per item on failure. */
279	  private runBatch(items: readonly { id: string; text: string }[]): Record<string, string> {
280	    const payload = Object.fromEntries(items.map((i) => [i.id, i.text]));
281	    const prompt = [
282	      "Translate the VALUES of this JSON object from English to Hungarian.",
283	      "Return ONLY a JSON object with the same keys and translated values.",
284	      "Do not translate, add, or remove keys. Keep identifiers, package names, and URLs unchanged.",
285	      JSON.stringify(payload, null, 2),
286	    ].join("\n");
287	
288	    const raw = this.runClaude(prompt, `batch of ${items.length} strings`);
289	    const parsed = extractJsonObject(raw);
290	    if (parsed) {
291	      const out: Record<string, string> = {};
292	      for (const item of items) {
293	        const value = parsed[item.id];
294	        out[item.id] = typeof value === "string" ? value : item.text;
295	      }
296	      return out;
297	    }
298	    // The model didn't return usable JSON; degrade to per-item translation rather than lose content.
299	    const out: Record<string, string> = {};
300	    for (const item of items) out[item.id] = this.translateText(item.text);
301	    return out;
302	  }
303	
304	  private runClaude(prompt: string, scope: string): string {
305	    const result = spawnSync(this.command, [...this.args, "-p"], {
306	      input: prompt,
307	      encoding: "utf8",
308	      maxBuffer: 20 * 1024 * 1024,
309	    });
310	
311	    if (result.status !== 0) {
312	      throw new Error(
313	        `Claude translation failed for ${scope} (exit ${result.status ?? -1}): ${result.stderr.trim()}`,
314	      );
315	    }
316	
317	    return result.stdout.trimEnd();
318	  }
319	}
320	
321	export const createTranslationAdapter = (): TranslationAdapter => {
322	  // A pluggable selector means we can drop in a richer provider later without changing callers.
323	  const selected = (process.env.DOCS_TRANSLATION_ADAPTER ?? "glossary").toLowerCase();
324	
325	  if (selected === "glossary") {
326	    return new GlossaryTranslationAdapter();
327	  }
328	
329	  if (selected === "claude-code") {
330	    return new ClaudeCodeTranslationAdapter();
331	  }
332	
333	  throw new Error(
334	    `Unsupported DOCS_TRANSLATION_ADAPTER: ${selected}. Supported adapters: glossary, claude-code`,
335	  );
336	};
