1	/**
2	 * A content-addressed translation memory plus the batch driver both locale pipelines share.
3	 *
4	 * The pipelines used to re-translate every file on every run — one `claude -p` spawn per API
5	 * markdown file and per sidebar label. This module cuts that to the diff: each translatable unit is
6	 * keyed by a hash of its source text, so unchanged content is served from a committed cache and only
7	 * new or edited units reach the adapter. Small units (sidebar labels) are objectified into a single
8	 * batched request; large markdown is translated per file on a miss to keep fidelity.
9	 *
10	 * The flow is: diff (hash vs. cache) → objectify (batch the misses) → translate → destructure (map
11	 * results back by hash) → save (prune to the units seen this run, write JSON).
12	 *
13	 * @module
14	 */
15	import { createHash } from "node:crypto";
16	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
17	import { join } from "node:path";
18	import type { TranslationAdapter } from "./api-translation.ts";
19	
20	/** A translatable unit. `markdown` is translated per file; `text` units are batched together. */
21	export interface TranslationUnit {
22	  kind: "markdown" | "text";
23	  source: string;
24	  /** Only used to label markdown units in adapter prompts/logs. */
25	  filePath?: string;
26	}
27	
28	/** The cache directory (committed — it's the reusable translation memory, not a build artifact). */
29	const cacheDir = join(import.meta.dirname, "..", "i18n-cache");
30	
31	/** The stable content key for a unit: `sha256(kind \0 source)`, hex. */
32	export function keyFor(kind: string, source: string): string {
33	  return createHash("sha256").update(`${kind}�${source}`).digest("hex");
34	}
35	
36	interface CacheFile {
37	  version: 1;
38	  entries: Record<string, string>;
39	}
40	
41	/** A per-locale, per-namespace translation memory backed by a committed JSON file. */
42	export class TranslationMemory {
43	  private readonly path: string;
44	  private readonly entries: Map<string, string>;
45	  private readonly used = new Set<string>();
46	  hits = 0;
47	  misses = 0;
48	
49	  private constructor(path: string, entries: Map<string, string>) {
50	    this.path = path;
51	    this.entries = entries;
52	  }
53	
54	  /** Load (or start) the memory for `<locale>.<namespace>.json`. */
55	  static load(locale: string, namespace: string): TranslationMemory {
56	    const path = join(cacheDir, `${locale}.${namespace}.json`);
57	    if (!existsSync(path)) return new TranslationMemory(path, new Map());
58	    const parsed = JSON.parse(readFileSync(path, "utf8")) as CacheFile;
59	    return new TranslationMemory(path, new Map(Object.entries(parsed.entries ?? {})));
60	  }
61	
62	  /** A cached translation for this unit, or `undefined`. Marks the key as used. */
63	  get(kind: string, source: string): string | undefined {
64	    const key = keyFor(kind, source);
65	    const hit = this.entries.get(key);
66	    if (hit !== undefined) {
67	      this.used.add(key);
68	      this.hits += 1;
69	    }
70	    return hit;
71	  }
72	
73	  /** Store a translation and mark its key as used. */
74	  set(kind: string, source: string, translation: string): void {
75	    const key = keyFor(kind, source);
76	    this.entries.set(key, translation);
77	    this.used.add(key);
78	    this.misses += 1;
79	  }
80	
81	  /** Prune to the keys touched this run, then write stable (sorted) JSON. */
82	  save(): void {
83	    const pruned: Record<string, string> = {};
84	    for (const key of [...this.used].sort()) {
85	      const value = this.entries.get(key);
86	      if (value !== undefined) pruned[key] = value;
87	    }
88	    mkdirSync(cacheDir, { recursive: true });
89	    const payload: CacheFile = { version: 1, entries: pruned };
90	    writeFileSync(this.path, `${JSON.stringify(payload, null, 2)}\n`);
91	  }
92	}
93	
94	/**
95	 * Translate a set of units against the memory. Returns a map keyed by `keyFor(kind, source)` so
96	 * callers can look up each unit's translation (identical sources collapse to one entry).
97	 *
98	 * Diff: cache hits are served immediately. Objectify + translate: `text` misses are deduped and sent
99	 * to {@link TranslationAdapter.translateBatch} in one request; `markdown` misses are translated per
100	 * file. Destructure + save: results are written back into the memory keyed by content hash.
101	 */
102	export interface TranslateOptions {
103	  /**
104	   * Persist the memory after each markdown miss, so a long run (e.g. hundreds of API files) is
105	   * resumable: if a translation fails partway, the completed work is already saved and a re-run
106	   * serves it from cache. Off by default.
107	   */
108	  autosave?: boolean;
109	}
110	
111	export function translateUnits(
112	  adapter: TranslationAdapter,
113	  memory: TranslationMemory,
114	  units: readonly TranslationUnit[],
115	  options: TranslateOptions = {},
116	): Map<string, string> {
117	  const result = new Map<string, string>();
118	
119	  // Dedupe by content key so an identical string (e.g. a repeated sidebar label) translates once.
120	  const unique = new Map<string, TranslationUnit>();
121	  for (const unit of units) {
122	    const key = keyFor(unit.kind, unit.source);
123	    const cached = memory.get(unit.kind, unit.source);
124	    if (cached !== undefined) {
125	      result.set(key, cached);
126	      continue;
127	    }
128	    if (!unique.has(key)) unique.set(key, unit);
129	  }
130	
131	  const misses = [...unique.values()];
132	  const textMisses = misses.filter((u) => u.kind === "text");
133	  const markdownMisses = misses.filter((u) => u.kind === "markdown");
134	
135	  // Markdown: per-file (keeps fidelity; batching large bodies risks the model dropping structure).
136	  // A single file's failure is logged and skipped rather than aborting the whole run.
137	  for (const [index, unit] of markdownMisses.entries()) {
138	    try {
139	      const translated = adapter.translateMarkdown(unit.source, unit.filePath ?? "");
140	      memory.set("markdown", unit.source, translated);
141	      result.set(keyFor("markdown", unit.source), translated);
142	      if (options.autosave) memory.save();
143	      if ((index + 1) % 25 === 0) {
144	        console.log(`  … ${index + 1}/${markdownMisses.length} markdown files translated`);
145	      }
146	    } catch (error) {
147	      console.warn(
148	        `  ! skipped ${unit.filePath ?? "a markdown unit"}: ${error instanceof Error ? error.message : String(error)}`,
149	      );
150	    }
151	  }
152	
153	  // Text: objectify into one batched request, then destructure by id.
154	  if (textMisses.length > 0) {
155	    const items = textMisses.map((u) => ({ id: keyFor("text", u.source), text: u.source }));
156	    const batched = adapter.translateBatch
157	      ? adapter.translateBatch(items)
158	      : Object.fromEntries(items.map((i) => [i.id, adapter.translateText(i.text)]));
159	    for (const unit of textMisses) {
160	      const key = keyFor("text", unit.source);
161	      const translated = batched[key] ?? unit.source;
162	      memory.set("text", unit.source, translated);
163	      result.set(key, translated);
164	    }
165	    if (options.autosave) memory.save();
166	  }
167	
168	  return result;
169	}
