129	export class GlossaryTranslationAdapter implements TranslationAdapter {
130	  readonly name = "glossary";
131	  // Deterministic term substitution only — it cannot translate prose, so the memory must never cache
132	  // its output under a prose key.
133	  readonly translatesProse = false;
134	
135	  translateMarkdown(input: string): string {
136	    return translateWithoutFencedCode(input, (text) => this.translateText(text));
137	  }
138	
139	  translateText(input: string): string {
140	    const preserved = preservePackageNames(input);
141	    let out = preserved.text;
142	    for (const [pattern, value] of SORTED_REPLACEMENTS) {
143	      out = out.replace(pattern, value);
144	    }
145	    return restorePackageNames(out, preserved.packageNames);
146	  }
147	
148	  translateBatch(
149	    items: readonly { id: string; text: string }[],
150	    onChunk?: (partial: Record<string, string>) => void,
151	  ): Record<string, string> {
152	    const out = Object.fromEntries(items.map((item) => [item.id, this.translateText(item.text)]));
153	    onChunk?.(out);
154	    return out;
155	  }
156	}
