158	const replaceBlocks = (
159	  input: string,
160	  pattern: RegExp,
161	  markerPrefix: string,
162	): { text: string; blocks: string[] } => {
163	  const blocks: string[] = [];
164	  const text = input.replace(pattern, (match) => {
165	    const marker = `__${markerPrefix}_${blocks.length}__`;
166	    blocks.push(match);
167	    return marker;
168	  });
169	  return { text, blocks };
170	};
171	
172	const restoreBlocks = (input: string, blocks: string[], markerPrefix: string): string => {
173	  let out = input;
174	  for (const [index, block] of blocks.entries()) {
175	    out = out.replaceAll(`__${markerPrefix}_${index}__`, block);
176	  }
177	  return out;
178	};
179	
180	const preserveMarkdownSensitiveBlocks = (
181	  input: string,
182	): {
183	  text: string;
184	  codeBlocks: string[];
185	  inlineCodeBlocks: string[];
186	} => {
187	  const fenced = replaceBlocks(input, /```[\s\S]*?```/g, "PTK_CODE_BLOCK");
188	  const inline = replaceBlocks(fenced.text, /`[^`\n]+`/g, "PTK_INLINE_CODE");
189	  return {
190	    text: inline.text,
191	    codeBlocks: fenced.blocks,
192	    inlineCodeBlocks: inline.blocks,
193	  };
194	};
195	
196	const restoreMarkdownSensitiveBlocks = (
197	  input: string,
198	  codeBlocks: string[],
199	  inlineCodeBlocks: string[],
200	): string => {
201	  const withCode = restoreBlocks(input, codeBlocks, "PTK_CODE_BLOCK");
202	  return restoreBlocks(withCode, inlineCodeBlocks, "PTK_INLINE_CODE");
203	};
204	
205	const preservePackageNames = (input: string): { text: string; packageNames: string[] } => {
206	  const packagePattern = /@[a-z0-9][a-z0-9.-]*\/[a-z0-9][a-z0-9.-]*/gi;
207	  const packageNames: string[] = [];
208	
209	  const text = input.replace(packagePattern, (match) => {
210	    const marker = `__PTK_PACKAGE_${packageNames.length}__`;
211	    packageNames.push(match);
212	    return marker;
213	  });
214	
215	  return { text, packageNames };
216	};
217	
218	/** Pull the first `{…}` JSON object out of a model response (tolerating code fences), or `null`. */
219	const extractJsonObject = (raw: string): Record<string, unknown> | null => {
220	  const start = raw.indexOf("{");
221	  const end = raw.lastIndexOf("}");
222	  if (start === -1 || end <= start) return null;
223	  try {
224	    const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
225	    return typeof parsed === "object" && parsed !== null
226	      ? (parsed as Record<string, unknown>)
227	      : null;
228	  } catch {
229	    return null;
230	  }
231	};
232	
233	const restorePackageNames = (input: string, packageNames: string[]): string => {
234	  let out = input;
235	  for (const [index, packageName] of packageNames.entries()) {
236	    out = out.replaceAll(`__PTK_PACKAGE_${index}__`, packageName);
237	  }
238	  return out;
239	};
240	
241	const translateWithoutFencedCode = (input: string, translate: (line: string) => string): string => {
242	  const lines = input.split("\n");
243	  const out: string[] = [];
244	  let inFence = false;
245	
246	  for (const line of lines) {
247	    if (line.trimStart().startsWith("```")) {
248	      inFence = !inFence;
249	      out.push(line);
250	      continue;
251	    }
252	
253	    if (inFence) {
254	      out.push(line);
255	      continue;
256	    }
257	
258	    out.push(translate(line));
259	  }
260	
261	  return out.join("\n");
262	};
