264	export class ClaudeCodeTranslationAdapter implements TranslationAdapter {
265	  readonly name = "claude-code";
266	
267	  private readonly command: string;
268	  private readonly args: string[];
269	
270	  constructor() {
271	    this.command = process.env.DOCS_TRANSLATION_COMMAND ?? "claude";
272	    this.args = (process.env.DOCS_TRANSLATION_COMMAND_ARGS ?? "")
273	      .split(" ")
274	      .map((part) => part.trim())
275	      .filter((part) => part.length > 0);
276	  }
277	
278	  translateMarkdown(input: string, filePath: string): string {
279	    const preservedMarkdown = preserveMarkdownSensitiveBlocks(input);
280	    const preservedPackages = preservePackageNames(preservedMarkdown.text);
281	    const prompt = [
282	      "Translate this technical markdown from English to Hungarian.",
283	      "Return only the translated markdown.",
284	      "Rules:",
285	      "- Keep markdown structure unchanged.",
286	      "- Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__ or __PTK_INLINE_CODE_#__.",
287	      "- Do not alter placeholder tokens like __PTK_PACKAGE_#__.",
288	      "- Preserve whitespace and line breaks.",
289	      "- Keep import paths, package names, URLs, and identifiers intact.",
290	      `File: ${filePath}`,
291	      "--- BEGIN MARKDOWN ---",
292	      preservedPackages.text,
293	      "--- END MARKDOWN ---",
294	    ].join("\n");
295	
296	    const translated = this.runClaude(prompt, `markdown file ${filePath}`);
297	    const restoredPackages = restorePackageNames(translated, preservedPackages.packageNames);
298	    return restoreMarkdownSensitiveBlocks(
299	      restoredPackages,
300	      preservedMarkdown.codeBlocks,
301	      preservedMarkdown.inlineCodeBlocks,
302	    );
303	  }
304	
305	  translateText(input: string): string {
306	    const preserved = preservePackageNames(input);
307	    const prompt = [
308	      "Translate this technical UI text from English to Hungarian.",
309	      "Return only the translation.",
310	      "Keep identifiers and package names unchanged.",
311	      "Do not alter placeholder tokens like __PTK_PACKAGE_#__.",
312	      "Text:",
313	      preserved.text,
314	    ].join("\n");
315	
316	    const translated = this.runClaude(prompt, "single text line").trim();
317	    return restorePackageNames(translated, preserved.packageNames);
318	  }
319	
320	  translateBatch(
321	    items: readonly { id: string; text: string }[],
322	    onChunk?: (partial: Record<string, string>) => void,
323	  ): Record<string, string> {
324	    const out: Record<string, string> = {};
325	    // Chunk by total character budget. Bigger chunks amortize the fixed per-call agent-startup cost
326	    // (each `claude -p` pays it once), so fewer/larger requests finish the whole tree faster; the
327	    // ceiling is JSON reliability — too many keys per response and the model may drop/truncate one,
328	    // which `runBatch` degrades to per-item translation. 12k is a safe middle ground; override via
329	    // DOCS_TRANSLATION_BATCH_BUDGET if a run trips that fallback.
330	    const BUDGET = Number(process.env.DOCS_TRANSLATION_BATCH_BUDGET) || 12000;
331	    let chunk: { id: string; text: string }[] = [];
332	    let size = 0;
333	    const flush = (): void => {
334	      if (chunk.length === 0) return;
335	      const partial = this.runBatch(chunk);
336	      Object.assign(out, partial);
337	      // Surface each chunk as it lands so the caller can persist + report progress across a long run.
338	      onChunk?.(partial);
339	      chunk = [];
340	      size = 0;
341	    };
342	    for (const item of items) {
343	      if (size + item.text.length > BUDGET && chunk.length > 0) flush();
344	      chunk.push(item);
345	      size += item.text.length;
346	    }
347	    flush();
348	    return out;
349	  }
350	
351	  /** Translate one chunk of short strings as a single JSON object; fall back per item on failure. */
352	  private runBatch(items: readonly { id: string; text: string }[]): Record<string, string> {
353	    // Protect code and package names in every value before it reaches the model — prose cells and
354	    // captions carry inline code and `@scope/pkg` names that must survive verbatim — then restore per
355	    // id. Without this the batch path (unlike translateMarkdown) would let the model rewrite them.
356	    const masked = items.map((item) => {
357	      const markdown = preserveMarkdownSensitiveBlocks(item.text);
358	      const packages = preservePackageNames(markdown.text);
359	      return { id: item.id, masked: packages.text, markdown, packages };
360	    });
361	    const restore = (entry: (typeof masked)[number], value: string): string =>
362	      restoreMarkdownSensitiveBlocks(
363	        restorePackageNames(value, entry.packages.packageNames),
364	        entry.markdown.codeBlocks,
365	        entry.markdown.inlineCodeBlocks,
366	      );
367	
368	    const payload = Object.fromEntries(masked.map((entry) => [entry.id, entry.masked]));
369	    const prompt = [
370	      "Translate the VALUES of this JSON object from English to Hungarian.",
371	      "Return ONLY a JSON object with the same keys and translated values.",
372	      "Do not translate, add, or remove keys. Keep identifiers, package names, and URLs unchanged.",
373	      "Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__, __PTK_INLINE_CODE_#__, or __PTK_PACKAGE_#__.",
374	      JSON.stringify(payload, null, 2),
375	    ].join("\n");
376	
377	    const raw = this.runClaude(prompt, `batch of ${items.length} strings`);
378	    const parsed = extractJsonObject(raw);
379	    if (parsed) {
380	      const out: Record<string, string> = {};
381	      for (const entry of masked) {
382	        const value = parsed[entry.id];
383	        // A missing/non-string value restores to the (masked → original) source rather than dropping it.
384	        out[entry.id] = restore(entry, typeof value === "string" ? value : entry.masked);
385	      }
386	      return out;
387	    }
388	    // The model didn't return usable JSON; degrade to per-item translation rather than lose content.
389	    const out: Record<string, string> = {};
390	    for (const item of items) out[item.id] = this.translateText(item.text);
391	    return out;
392	  }
393	
394	  private runClaude(prompt: string, scope: string): string {
395	    const result = spawnSync(this.command, [...this.args, "-p"], {
396	      input: prompt,
397	      encoding: "utf8",
398	      maxBuffer: 20 * 1024 * 1024,
399	    });
400	
401	    if (result.status !== 0) {
402	      throw new Error(
403	        `Claude translation failed for ${scope} (exit ${result.status ?? -1}): ${result.stderr.trim()}`,
404	      );
405	    }
406	
407	    return result.stdout.trimEnd();
408	  }
409	}
410	
411	export const createTranslationAdapter = (): TranslationAdapter => {
412	  // A pluggable selector means we can drop in a richer provider later without changing callers.
413	  const selected = (process.env.DOCS_TRANSLATION_ADAPTER ?? "glossary").toLowerCase();
414	
415	  if (selected === "glossary") {
416	    return new GlossaryTranslationAdapter();
417	  }
418	
419	  if (selected === "claude-code") {
420	    return new ClaudeCodeTranslationAdapter();
421	  }
422	
423	  throw new Error(
424	    `Unsupported DOCS_TRANSLATION_ADAPTER: ${selected}. Supported adapters: glossary, claude-code`,
425	  );
426	};
